import { useEffect, useState } from 'react';
import { ActivityIndicator, Alert, Image, KeyboardAvoidingView, Modal, Platform, Pressable, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { LinearGradient } from 'expo-linear-gradient';
import * as ImagePicker from 'expo-image-picker';
import { AudioModule, RecordingPresets, setAudioModeAsync, useAudioPlayer, useAudioPlayerStatus, useAudioRecorder, useAudioRecorderState } from 'expo-audio';
import { api } from '../services/api';
import { colors } from '../theme';
import type { ChapterBlock, PublicationMedia } from '../types';

type Asset = { uri: string; name: string; type: string };
type LocalBlock = Omit<ChapterBlock, 'order' | 'media'> & { order?: number; media?: PublicationMedia; asset?: Asset };
type LocalChapter = { id: string; title: string; blocks: LocalBlock[] };
const uid = (prefix: string) => `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
const freshChapter = (number: number): LocalChapter => ({ id: uid('chapter'), title: number === 1 ? '' : `Chapter ${number}`, blocks: [{ id: uid('text'), type: 'TEXT', text: '' }] });
const blockLabel: Record<string, string> = { TEXT: 'Story', HIGHLIGHT: 'Marker', KEY_POINT: 'Key point', LIST: 'List', POLL: 'Poll', IMAGE: 'Photo', LINK: 'Link', VOICE: 'Voice' };

export function SeenComposer({ accessToken, onBack, onPublished }: { accessToken: string; onBack: () => void; onPublished: () => void }) {
  const [cover, setCover] = useState<Asset | null>(null);
  const [title, setTitle] = useState('');
  const [summary, setSummary] = useState('');
  const [category, setCategory] = useState('Lifestyle');
  const [categories, setCategories] = useState(['Places', 'Moving', 'Business', 'Growth', 'Lifestyle']);
  const [settingsSheet, setSettingsSheet] = useState<'category' | 'cover' | 'series' | 'people' | 'location' | 'audience' | 'experience' | null>(null);
  const [visibility, setVisibility] = useState<'PUBLIC' | 'FOLLOWERS' | 'LINK_ONLY'>('PUBLIC');
  const [allowDownload, setAllowDownload] = useState(false);
  const [experienceLocation, setExperienceLocation] = useState('');
  const [series, setSeries] = useState<{ id: string; name: string } | null>(null);
  const [seriesItems, setSeriesItems] = useState<{ id: string; name: string }[]>([]);
  const [seriesName, setSeriesName] = useState('');
  const [taggedPeople, setTaggedPeople] = useState<{ id: string; name: string }[]>([]);
  const [peopleQuery, setPeopleQuery] = useState('');
  const [peopleResults, setPeopleResults] = useState<{ id: string; name: string }[]>([]);
  const [chapters, setChapters] = useState<LocalChapter[]>([]);
  const [editing, setEditing] = useState<string | null>(null);
  const [previewing, setPreviewing] = useState(false);
  const [busy, setBusy] = useState(false);
  const [progress, setProgress] = useState('');
  const [error, setError] = useState('');

  useEffect(() => { api.listSeenCategories(accessToken).then((result) => { if (result.categories.length) setCategories(result.categories.map((item) => item.name)); }).catch(() => undefined); api.listMySeries(accessToken).then((result) => setSeriesItems(result.items || [])).catch(() => undefined); }, [accessToken]);
  useEffect(() => { if (settingsSheet !== 'people') return; let active = true; const timer = setTimeout(() => api.listShareRecipients(peopleQuery, accessToken).then((result) => { if (active) setPeopleResults((result.people || []).map((person) => ({ id: person.id, name: person.displayName || person.name || person.username || 'Member' }))); }).catch(() => undefined), 250); return () => { active = false; clearTimeout(timer); }; }, [accessToken, peopleQuery, settingsSheet]);
  const active = chapters.find((chapter) => chapter.id === editing) || null;
  const updateChapter = (id: string, update: Partial<LocalChapter>) => setChapters((items) => items.map((item) => item.id === id ? { ...item, ...update } : item));
  const moveChapter = (index: number, direction: -1 | 1) => setChapters((items) => { const target = index + direction; if (target < 0 || target >= items.length) return items; const next = [...items]; [next[index], next[target]] = [next[target], next[index]]; return next; });
  const removeChapter = (id: string) => Alert.alert('Remove chapter?', 'This removes the chapter and everything inside it.', [{ text: 'Keep', style: 'cancel' }, { text: 'Remove', style: 'destructive', onPress: () => setChapters((items) => items.filter((item) => item.id !== id)) }]);

  const pick = async (media: 'images' | 'videos', target: 'cover' | 'block', chapterId?: string) => {
    setError('');
    const permission = await ImagePicker.requestMediaLibraryPermissionsAsync();
    if (!permission.granted) return setError('Photo library permission is required.');
    const result = await ImagePicker.launchImageLibraryAsync({ mediaTypes: [media], quality: .9, allowsEditing: media === 'images' });
    if (result.canceled) return;
    const item = result.assets[0];
    if (media === 'videos' && item.duration && item.duration > 30000) return setError('Seen cover videos must be 30 seconds or shorter.');
    const asset = { uri: item.uri, name: item.fileName || `seen-${Date.now()}.${media === 'videos' ? 'mp4' : 'jpg'}`, type: item.mimeType || (media === 'videos' ? 'video/mp4' : 'image/jpeg') };
    if (target === 'cover') setCover(asset);
    else if (chapterId) setChapters((items) => items.map((chapter) => {
      if (chapter.id !== chapterId) return chapter;
      if (chapter.blocks.length >= 6) { Alert.alert('Chapter is full', 'A chapter can contain up to six blocks.'); return chapter; }
      return { ...chapter, blocks: [...chapter.blocks, { id: uid('image'), type: 'IMAGE', asset }] };
    }));
  };

  const validate = () => {
    if (!cover || !title.trim() || !summary.trim()) return 'Add a cover, title, and description.';
    if (!chapters.length) return 'Add at least one chapter.';
    for (const [index, chapter] of chapters.entries()) {
      if (!chapter.title.trim()) return `Chapter ${index + 1} needs a name.`;
      if (!chapter.blocks.length) return `${chapter.title} needs at least one block.`;
      for (const block of chapter.blocks) {
        if (['TEXT', 'HIGHLIGHT', 'KEY_POINT'].includes(block.type) && !block.text?.trim()) return `${chapter.title} has an empty ${blockLabel[block.type].toLowerCase()} block.`;
        if (block.type === 'LIST' && !String(block.text || '').split('\n').filter((line) => line.trim()).length) return `${chapter.title} has an empty list.`;
        if (block.type === 'POLL') { const meta = block.metadata as { question?: string; options?: string[] } | undefined; if (!meta?.question?.trim() || (meta.options || []).filter((value) => value.trim()).length < 2) return `${chapter.title} needs a poll question and two answers.`; }
      }
    }
    return '';
  };

  const normalized = (blocks: LocalBlock[]): ChapterBlock[] => blocks.filter((block) => (block.type !== 'TEXT' || Boolean(block.text?.trim())) && (!['IMAGE', 'VIDEO', 'AUDIO', 'VOICE'].includes(block.type) || block.media)).map((block, order) => {
    if (block.type === 'LIST') { const listItems = String(block.text || '').split('\n').map((item) => item.trim()).filter(Boolean); return { id: block.id, type: 'LIST', order, text: listItems.join('\n'), metadata: { listItems } }; }
    if (block.type === 'POLL') { const meta = block.metadata as { question?: string; options?: string[]; resultsVisibility?: string }; return { id: block.id, type: 'POLL', order, metadata: { question: meta.question?.trim(), options: (meta.options || []).map((item) => item.trim()).filter(Boolean), resultsVisibility: meta.resultsVisibility || 'SUBSCRIBERS' } }; }
    return { ...block, order, asset: undefined } as ChapterBlock;
  });

  const persist = async (shouldPublish: boolean) => {
    const problem = shouldPublish ? validate() : (!title.trim() ? 'Add a title before saving this draft.' : ''); if (problem) return setError(problem);
    setBusy(true); setError('');
    try {
      setProgress('Creating draft…');
      const draft = (await api.createSeenDraft({ title: title.trim(), summary: summary.trim(), category, visibility, allowDownload, experienceLocation: experienceLocation.trim(), taggedPeople: taggedPeople.map((person) => person.id), seriesId: series?.id || null }, accessToken)).publication;
      if (cover) { setProgress('Uploading cover…'); await api.uploadSeenCover(draft.id, cover, draft.statusVersion, accessToken); }
      let current = (await api.getMyPublication(draft.id, accessToken)).publication;
      for (let index = 0; index < chapters.length; index += 1) {
        const local = chapters[index]; setProgress(`Saving chapter ${index + 1} of ${chapters.length}…`);
        const added = await api.addSeenChapter(draft.id, local.title.trim(), normalized(local.blocks), current.statusVersion, accessToken);
        current = (await api.getMyPublication(draft.id, accessToken)).publication;
        const pending = local.blocks.filter((block) => ['IMAGE', 'VIDEO', 'AUDIO', 'VOICE'].includes(block.type) && block.asset);
        if (pending.length) {
          const complete = [...local.blocks];
          for (const block of pending) {
            setProgress(`Uploading chapter ${index + 1} photo…`);
            const media = await api.uploadSeenBlock(draft.id, added.chapter.stableChapterId, block.id, block.type as 'IMAGE' | 'VIDEO' | 'AUDIO' | 'VOICE', block.asset!, accessToken);
            const found = complete.find((item) => item.id === block.id); if (found) found.media = media;
          }
          await api.updateSeenChapter(draft.id, added.chapter.stableChapterId, local.title.trim(), normalized(complete), current.statusVersion, accessToken);
          current = (await api.getMyPublication(draft.id, accessToken)).publication;
        }
      }
      if (shouldPublish) { setProgress('Publishing…'); await api.submitSeen(draft.id, current.statusVersion, accessToken); }
      onPublished();
    } catch (reason) { setError(reason instanceof Error ? reason.message : `Could not ${shouldPublish ? 'publish' : 'save'} this Seen.`); }
    finally { setBusy(false); setProgress(''); }
  };
  const publish = () => persist(true);
  const saveForLater = () => persist(false);

  if (active) return <ChapterEditor accessToken={accessToken} chapter={active} onBack={() => setEditing(null)} onChange={(next) => updateChapter(active.id, next)} onPickPhoto={() => pick('images', 'block', active.id)} />;
  if (previewing) return <SeenPreview cover={cover} title={title} summary={summary} chapters={chapters} onBack={() => setPreviewing(false)} />;
  return <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined} style={s.screen}>
    <View style={s.header}><Pressable disabled={busy} onPress={onBack} style={s.composeBack}><Ionicons color="rgba(255,255,255,.72)" name="chevron-back" size={22} /></Pressable><View style={s.headerCopy}><Text style={s.headerTitle}>New Seen</Text><Text style={s.headerSub}>Seen — a post made of chapters. People walk it like a small story.</Text></View><Pressable disabled={busy} onPress={saveForLater} style={s.saveLater}><Ionicons color={colors.blue} name="save-outline" size={14} /><Text style={s.saveLaterText}>Save for later</Text></Pressable></View>
    <ScrollView contentContainerStyle={s.content} keyboardShouldPersistTaps="handled" showsVerticalScrollIndicator={false}>
      {cover ? <View style={s.cover}>{cover.type.startsWith('image/') ? <Image source={{ uri: cover.uri }} style={StyleSheet.absoluteFill} /> : <View style={s.video}><Ionicons color={colors.blue} name="videocam" size={34} /><Text style={s.muted}>{cover.name}</Text></View>}<LinearGradient colors={['transparent', 'rgba(5,7,10,.82)']} style={StyleSheet.absoluteFill} /><Pressable onPress={() => setCover(null)} style={s.removeCover}><Ionicons color="#fff" name="close" size={16} /></Pressable></View> : <View style={s.mediaRow}><MediaButton icon="videocam-outline" label="Video · 0:15" onPress={() => pick('videos', 'cover')} /><MediaButton icon="videocam-outline" label="Video · 0:30" onPress={() => pick('videos', 'cover')} /><MediaButton icon="image-outline" label="Photo" onPress={() => pick('images', 'cover')} /></View>}
      <TextInput maxLength={120} onChangeText={setTitle} placeholder="Title — e.g. ‘A quiet morning’" placeholderTextColor={colors.faint} style={s.titleInput} value={title} />
      <TextInput maxLength={300} multiline onChangeText={setSummary} placeholder="About this Seen — what happens inside, honestly" placeholderTextColor={colors.faint} style={s.summaryInput} textAlignVertical="top" value={summary} />
      <View style={s.sectionHead}><Text style={s.label}>CHAPTERS</Text><Text style={s.mini}>{chapters.length}/5 · up to 6 blocks each</Text></View>
      <Text style={s.help}>Open a chapter to write its story and add photos, markers, key points, lists, or a poll.</Text>
      <View style={s.chapterList}>{chapters.map((chapter, index) => { const storyText = chapter.blocks.find((block) => block.type === 'TEXT')?.text?.trim() || ''; return <View key={chapter.id} style={s.chapterCard}><View style={s.chapterNumber}><Text style={s.chapterNumberText}>{index + 1}</Text></View><View style={s.chapterCopy}><TextInput maxLength={120} onChangeText={(value) => updateChapter(chapter.id, { title: value })} placeholder="Chapter name" placeholderTextColor={colors.faint} style={s.chapterTitleInput} value={chapter.title} />{storyText ? <Text numberOfLines={1} style={s.chapterMeta}>{storyText}</Text> : null}<Pressable onPress={() => setEditing(chapter.id)}><Text style={s.editStory}>{storyText ? 'Edit the story  ›' : '＋ Write the story  ›'}</Text></Pressable></View><Pressable onPress={() => removeChapter(chapter.id)} hitSlop={10}><Ionicons color={colors.faint} name="close" size={17} /></Pressable></View>; })}{chapters.length < 5 ? <Pressable onPress={() => { const chapter = freshChapter(chapters.length + 1); setChapters((items) => [...items, chapter]); }} style={s.addChapter}><Text style={s.addChapterText}>＋ {chapters.length ? 'Add chapter' : 'Chapter 1 — where it starts'}</Text></Pressable> : null}</View>
      <View style={s.settingsList}><ComposeSetting icon="pricetag-outline" label="Category" onPress={() => setSettingsSheet('category')} value={category || '—'} /><ComposeSetting icon="image-outline" label="Cover" onPress={() => setSettingsSheet('cover')} value={cover ? 'Added' : 'Add'} /><ComposeSetting icon="grid-outline" label="Series" onPress={() => setSettingsSheet('series')} value={series?.name || 'None'} /><ComposeSetting icon="people-outline" label="Tag people" onPress={() => setSettingsSheet('people')} value={taggedPeople.length ? `${taggedPeople.length} tagged` : 'None'} /><ComposeSetting icon="location-outline" label="Location" onPress={() => setSettingsSheet('location')} value={experienceLocation || 'Add'} /><ComposeSetting icon={visibility === 'LINK_ONLY' ? 'link-outline' : visibility === 'FOLLOWERS' ? 'people-outline' : 'globe-outline'} label="Audience" onPress={() => setSettingsSheet('audience')} value={visibility === 'PUBLIC' ? 'Everyone' : visibility === 'FOLLOWERS' ? 'Followers' : 'Anyone with link'} /><ComposeSetting icon="download-outline" label="Allow download" onPress={() => setAllowDownload((value) => !value)} toggle value={allowDownload ? 'On' : 'Off'} /><ComposeSetting icon="film-outline" label="Part of an Experience" onPress={() => setSettingsSheet('experience')} value="None" /></View>
      {error ? <Text style={s.error}>{error}</Text> : null}{progress ? <Text style={s.progress}>{progress}</Text> : null}
      <Pressable disabled={busy} onPress={publish} style={[s.publish, busy && s.disabled]}><LinearGradient colors={['#A9D4FF', '#77B4F0']} style={s.publishInner}>{busy ? <ActivityIndicator color="#07101A" /> : <Text style={s.publishText}>Publish</Text>}</LinearGradient></Pressable><Pressable disabled={busy} onPress={onBack} style={s.cancel}><Text style={s.cancelText}>Cancel</Text></Pressable>
    </ScrollView>
    <ComposerSettingsSheet accessToken={accessToken} categories={categories} category={category} cover={cover} peopleQuery={peopleQuery} peopleResults={peopleResults} selectedPeople={taggedPeople} series={series} seriesItems={seriesItems} seriesName={seriesName} sheet={settingsSheet} value={experienceLocation} visibility={visibility} onClose={() => setSettingsSheet(null)} onCreateSeries={async () => { if (!seriesName.trim()) return; const created = (await api.createSeries(seriesName.trim(), accessToken)).series; setSeriesItems((items) => [...items, created]); setSeries(created); setSeriesName(''); setSettingsSheet(null); }} onCover={() => { setSettingsSheet(null); pick('images', 'cover'); }} onPeopleQuery={setPeopleQuery} onSelectCategory={(value) => { setCategory(value); setSettingsSheet(null); }} onSelectLocation={(value) => { setExperienceLocation(value); setSettingsSheet(null); }} onSelectPerson={(person) => setTaggedPeople((items) => items.some((item) => item.id === person.id) ? items.filter((item) => item.id !== person.id) : [...items, person])} onSelectSeries={(value) => { setSeries(value); setSettingsSheet(null); }} onSeriesName={setSeriesName} onVisibility={(value) => { setVisibility(value); setSettingsSheet(null); }} />
  </KeyboardAvoidingView>;
}

function ComposeSetting({ icon, label, onPress, toggle = false, value }: { icon: keyof typeof Ionicons.glyphMap; label: string; onPress: () => void; toggle?: boolean; value: string }) { return <Pressable onPress={onPress} style={s.composeSetting}><Ionicons color="rgba(255,255,255,.4)" name={icon} size={17} /><Text style={s.composeSettingLabel}>{label}</Text><Text style={s.composeSettingValue}>{value}</Text>{toggle ? <View style={[s.toggle, value === 'On' && s.toggleOn]}><View style={[s.toggleKnob, value === 'On' && s.toggleKnobOn]} /></View> : <Ionicons color={colors.faint} name="chevron-forward" size={14} />}</Pressable>; }
type SettingsSheet = 'category' | 'cover' | 'series' | 'people' | 'location' | 'audience' | 'experience' | null;
function ComposerSettingsSheet(props: { accessToken: string; categories: string[]; category: string; cover: Asset | null; peopleQuery: string; peopleResults: { id: string; name: string }[]; selectedPeople: { id: string; name: string }[]; series: { id: string; name: string } | null; seriesItems: { id: string; name: string }[]; seriesName: string; sheet: SettingsSheet; value: string; visibility: 'PUBLIC' | 'FOLLOWERS' | 'LINK_ONLY'; onClose: () => void; onCover: () => void; onCreateSeries: () => void; onPeopleQuery: (value: string) => void; onSelectCategory: (value: string) => void; onSelectLocation: (value: string) => void; onSelectPerson: (person: { id: string; name: string }) => void; onSelectSeries: (series: { id: string; name: string } | null) => void; onSeriesName: (value: string) => void; onVisibility: (value: 'PUBLIC' | 'FOLLOWERS' | 'LINK_ONLY') => void }) {
  const { categories, category, cover, peopleQuery, peopleResults, selectedPeople, series, seriesItems, seriesName, sheet, value, visibility } = props;
  if (!sheet) return null;
  const title = sheet === 'category' ? 'Category' : sheet === 'cover' ? 'Cover' : sheet === 'series' ? 'Series' : sheet === 'people' ? 'Tag people' : sheet === 'location' ? 'Location' : sheet === 'audience' ? 'Audience' : 'Part of an Experience';
  return <Modal animationType="slide" onRequestClose={props.onClose} transparent visible><View style={s.sheetWrap}><Pressable onPress={props.onClose} style={StyleSheet.absoluteFill} /><KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined} style={s.settingsSheet}><View style={s.sheetHandle} /><View style={s.settingsSheetHead}><Text style={s.sheetTitle}>{title}</Text><Pressable onPress={props.onClose}><Ionicons color={colors.muted} name="close" size={20} /></Pressable></View>
    {sheet === 'category' ? categories.map((item) => <SheetOption active={item === category} key={item} label={item} onPress={() => props.onSelectCategory(item)} />) : null}
    {sheet === 'cover' ? <View><View style={s.coverSheetPreview}>{cover ? <Ionicons color={colors.blue} name="checkmark" size={28} /> : <Ionicons color={colors.blue} name="image-outline" size={28} />}</View><Pressable onPress={props.onCover} style={s.sheetSave}><Text style={s.sheetSaveText}>{cover ? 'Replace' : 'Upload'}</Text></Pressable></View> : null}
    {sheet === 'series' ? <View>{seriesItems.map((item) => <SheetOption active={series?.id === item.id} key={item.id} label={item.name} onPress={() => props.onSelectSeries(item)} />)}<SheetOption active={!series} label="None" onPress={() => props.onSelectSeries(null)} /><View style={s.createSeries}><TextInput maxLength={24} onChangeText={props.onSeriesName} placeholder="New Series name" placeholderTextColor={colors.faint} style={s.sheetInput} value={seriesName} /><Pressable onPress={props.onCreateSeries}><Text style={s.sheetAction}>Create</Text></Pressable></View></View> : null}
    {sheet === 'people' ? <View><TextInput autoFocus onChangeText={props.onPeopleQuery} placeholder="Search people" placeholderTextColor={colors.faint} style={s.sheetInput} value={peopleQuery} />{peopleResults.map((person) => <SheetOption active={selectedPeople.some((item) => item.id === person.id)} key={person.id} label={person.name} onPress={() => props.onSelectPerson(person)} />)}<Pressable onPress={props.onClose} style={s.sheetSave}><Text style={s.sheetSaveText}>Done</Text></Pressable></View> : null}
    {sheet === 'location' ? <View><TextInput autoFocus defaultValue={value} onSubmitEditing={(event) => props.onSelectLocation(event.nativeEvent.text)} placeholder="Search a country or city" placeholderTextColor={colors.faint} style={s.sheetInput} /><Text style={s.settingsHelp}>Press return to use this location.</Text></View> : null}
    {sheet === 'audience' ? <View><SheetOption active={visibility === 'PUBLIC'} detail="Visible to everyone" label="Everyone" onPress={() => props.onVisibility('PUBLIC')} /><SheetOption active={visibility === 'FOLLOWERS'} detail="Only people who follow you" label="Followers" onPress={() => props.onVisibility('FOLLOWERS')} /><SheetOption active={visibility === 'LINK_ONLY'} detail="Hidden from your profile and Seen" label="Anyone with the link" onPress={() => props.onVisibility('LINK_ONLY')} /></View> : null}
    {sheet === 'experience' ? <View style={s.emptySheet}><Ionicons color={colors.blue} name="film-outline" size={28} /><Text style={s.settingsHelp}>No Experiences available to attach.</Text><Pressable onPress={props.onClose} style={s.sheetSave}><Text style={s.sheetSaveText}>Done</Text></Pressable></View> : null}
  </KeyboardAvoidingView></View></Modal>;
}
function SheetOption({ active, detail, label, onPress }: { active: boolean; detail?: string; label: string; onPress: () => void }) { return <Pressable onPress={onPress} style={[s.sheetOption, active && s.sheetOptionOn]}><View style={{ flex: 1 }}><Text style={s.sheetOptionLabel}>{label}</Text>{detail ? <Text style={s.sheetOptionDetail}>{detail}</Text> : null}</View>{active ? <Ionicons color={colors.blue} name="checkmark" size={18} /> : null}</Pressable>; }

function ChapterEditor({ accessToken, chapter, onBack, onChange, onPickPhoto }: { accessToken: string; chapter: LocalChapter; onBack: () => void; onChange: (value: Partial<LocalChapter>) => void; onPickPhoto: () => void }) {
  const [sheet, setSheet] = useState<'tools' | 'voice' | 'place' | 'link' | 'list' | 'poll' | 'marker' | null>(null);
  const [draft, setDraft] = useState({ label: '', url: '', text: '', question: '', options: ['', ''], visibility: 'SUBSCRIBERS' });
  const [placeQuery, setPlaceQuery] = useState('');
  const [places, setPlaces] = useState<string[]>([]);
  const [searching, setSearching] = useState(false);
  const [voiceError, setVoiceError] = useState('');
  const recorder = useAudioRecorder(RecordingPresets.HIGH_QUALITY);
  const recorderState = useAudioRecorderState(recorder, 250);
  const blocks = chapter.blocks;
  const story = blocks.find((block) => block.type === 'TEXT' && !block.metadata?.location);
  const visibleBlocks = blocks.filter((block) => block.id !== story?.id);
  const updateBlock = (id: string, change: Partial<LocalBlock>) => onChange({ blocks: blocks.map((block) => block.id === id ? { ...block, ...change } : block) });
  const removeBlock = (id: string) => onChange({ blocks: blocks.filter((block) => block.id !== id) });
  const moveBlock = (id: string, direction: -1 | 1) => { const index = blocks.findIndex((block) => block.id === id); const target = index + direction; if (index < 0 || target < 0 || target >= blocks.length) return; const next = [...blocks]; [next[index], next[target]] = [next[target], next[index]]; onChange({ blocks: next }); };
  const append = (block: LocalBlock) => { if (blocks.length >= 6) return Alert.alert('Chapter is full', 'A chapter can contain up to six blocks.'); onChange({ blocks: [...blocks, block] }); setSheet(null); };
  const openForm = (next: typeof sheet) => { setDraft({ label: '', url: '', text: '', question: '', options: ['', ''], visibility: 'SUBSCRIBERS' }); setSheet(next); };

  useEffect(() => {
    if (sheet !== 'place' || placeQuery.trim().length < 2) { setPlaces([]); return; }
    let active = true; const timer = setTimeout(() => { setSearching(true); api.searchPlaces(placeQuery, accessToken).then((result) => { if (active) setPlaces((result.suggestions || []).filter((item) => item.type === 'place').map((item) => item.title || item.subtitle || '').filter(Boolean).slice(0, 6)); }).catch(() => { if (active) setPlaces([]); }).finally(() => { if (active) setSearching(false); }); }, 300);
    return () => { active = false; clearTimeout(timer); };
  }, [accessToken, placeQuery, sheet]);

  const startRecording = async () => {
    setVoiceError(''); const permission = await AudioModule.requestRecordingPermissionsAsync();
    if (!permission.granted) return setVoiceError('Microphone permission is required.');
    await setAudioModeAsync({ allowsRecording: true, playsInSilentMode: true });
    await recorder.prepareToRecordAsync(); recorder.record();
  };
  const stopRecording = async () => {
    await recorder.stop(); const uri = recorder.uri; if (!uri) return setVoiceError('The recording could not be saved.');
    const asset: Asset = { uri, name: `voice-${Date.now()}.m4a`, type: 'audio/mp4' };
    let metadata: Record<string, unknown> = {};
    try { const result = await api.transcribeVoice(asset, accessToken); metadata = { transcript: result.transcript || '', transcriptConfidence: result.confidence, transcriptLanguage: result.detectedLanguage || result.language || '', transcriptProvider: result.provider || '' }; } catch { setVoiceError('Voice saved. A transcript could not be generated.'); }
    append({ id: uid('voice'), type: 'VOICE', asset, metadata });
    await setAudioModeAsync({ allowsRecording: false, playsInSilentMode: true });
  };
  const saveForm = () => {
    if (sheet === 'link') { const value = draft.url.trim(); if (!/^https?:\/\//i.test(value)) return setVoiceError('Add a full http or https link.'); append({ id: uid('link'), type: 'LINK', url: value, label: draft.label.trim() || value.replace(/^https?:\/\//i, '').split('/')[0] }); }
    if (sheet === 'list') { const items = draft.text.split('\n').map((item) => item.trim()).filter(Boolean); if (!items.length) return setVoiceError('Add at least one list item.'); append({ id: uid('list'), type: 'LIST', text: items.join('\n'), metadata: { listItems: items } }); }
    if (sheet === 'poll') { const options = draft.options.map((item) => item.trim()).filter(Boolean); if (!draft.question.trim() || options.length < 2) return setVoiceError('Add a question and at least two answers.'); append({ id: uid('poll'), type: 'POLL', metadata: { question: draft.question.trim(), options, resultsVisibility: draft.visibility } }); }
    if (sheet === 'marker') { if (!draft.text.trim()) return setVoiceError('Write the marker text.'); append({ id: uid('marker'), type: 'HIGHLIGHT', text: draft.text.trim(), metadata: { color: 'ICE_BLUE' } }); }
  };
  const addPlace = (label: string) => { const value = label.trim(); if (!value) return; append({ id: uid('place'), type: 'KEY_POINT', text: value, metadata: { location: { label: value } } }); setPlaceQuery(''); };

  return <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined} style={s.chapterCanvas}>
    <View style={s.canvasHeader}><View><TextInput maxLength={120} onChangeText={(title) => onChange({ title })} placeholder="Chapter name" placeholderTextColor="rgba(255,255,255,.35)" style={s.canvasTitle} value={chapter.title} /><Text style={s.canvasHint}>One moment. One thought. Keep it honest.</Text></View><Pressable onPress={onBack} style={s.canvasDone}><Text style={s.canvasDoneText}>Done</Text></Pressable></View>
    <ScrollView contentContainerStyle={s.canvasContent} keyboardShouldPersistTaps="handled" showsVerticalScrollIndicator={false}>
      <TextInput maxLength={2000} multiline onChangeText={(text) => story ? updateBlock(story.id, { text }) : onChange({ blocks: [{ id: uid('text'), type: 'TEXT', text }, ...blocks] })} placeholder={'Start writing…\n\nThis is your space. Say what happened.'} placeholderTextColor="rgba(255,255,255,.23)" style={s.canvasStory} textAlignVertical="top" value={story?.text || ''} />
      {visibleBlocks.map((block) => <CanvasBlock block={block} key={block.id} onChange={(change) => updateBlock(block.id, change)} onMove={(direction) => moveBlock(block.id, direction)} onRemove={() => removeBlock(block.id)} />)}
    </ScrollView>
    <Pressable onPress={() => setSheet('tools')} style={s.floatingAdd}><Ionicons color="#07101A" name="add" size={27} /></Pressable>
    <Modal animationType="slide" onRequestClose={() => setSheet(null)} transparent visible={Boolean(sheet)}><View style={s.sheetWrap}><Pressable onPress={() => setSheet(null)} style={StyleSheet.absoluteFill} /><KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined} style={s.editorSheet}><View style={s.sheetHandle} />
      {sheet === 'tools' ? <><Text style={s.sheetTitle}>Add to this chapter</Text><View style={s.sheetTools}><Tool icon="image-outline" label="Photo" onPress={() => { setSheet(null); onPickPhoto(); }} /><Tool icon="mic-outline" label="Voice" onPress={() => setSheet('voice')} /><Tool icon="location-outline" label="Place" onPress={() => setSheet('place')} /><Tool icon="link-outline" label="Link" onPress={() => openForm('link')} /><Tool icon="list-outline" label="List" onPress={() => openForm('list')} /><Tool icon="bar-chart-outline" label="Poll" onPress={() => openForm('poll')} /><Tool icon="color-wand-outline" label="Marker" onPress={() => openForm('marker')} /></View></> : null}
      {sheet === 'voice' ? <View style={s.voiceSheet}><Pressable onPress={recorderState.isRecording ? stopRecording : startRecording} style={[s.recordButton, recorderState.isRecording && s.recordButtonLive]}>{recorderState.isRecording ? <View style={s.stopSquare} /> : <Ionicons color="#07101A" name="mic" size={27} />}</Pressable><Text style={s.voiceTitle}>{recorderState.isRecording ? 'Recording…' : 'Add your voice'}</Text><Text style={s.voiceCopy}>You’ll get both — your voice and generated text. You can edit the transcript later.</Text>{recorderState.isRecording ? <Text style={s.recordTime}>{Math.floor(recorderState.durationMillis / 60000)}:{String(Math.floor(recorderState.durationMillis / 1000) % 60).padStart(2, '0')}</Text> : null}</View> : null}
      {sheet === 'place' ? <View><Text style={s.sheetTitle}>Add location</Text><View style={s.sheetInline}><TextInput autoFocus onChangeText={setPlaceQuery} onSubmitEditing={() => addPlace(placeQuery)} placeholder="Place — e.g. Lisbon, Alfama" placeholderTextColor={colors.faint} style={s.sheetInput} value={placeQuery} /><Pressable onPress={() => addPlace(placeQuery)}><Text style={s.sheetAction}>Add</Text></Pressable></View>{searching ? <ActivityIndicator color={colors.blue} style={{ marginTop: 12 }} /> : places.map((place) => <Pressable key={place} onPress={() => addPlace(place)} style={s.placeResult}><Ionicons color={colors.blue} name="location-outline" size={15} /><Text style={s.placeText}>{place}</Text></Pressable>)}</View> : null}
      {sheet === 'link' ? <View><Text style={s.sheetTitle}>Add link</Text><TextInput autoCapitalize="none" autoFocus onChangeText={(url) => setDraft((value) => ({ ...value, url }))} placeholder="https://…" placeholderTextColor={colors.faint} style={s.sheetInput} value={draft.url} /><TextInput onChangeText={(label) => setDraft((value) => ({ ...value, label }))} placeholder="Link title (optional)" placeholderTextColor={colors.faint} style={s.sheetInput} value={draft.label} /><SheetSave onPress={saveForm} /></View> : null}
      {sheet === 'list' || sheet === 'marker' ? <View><Text style={s.sheetTitle}>{sheet === 'list' ? 'Add a list' : 'Add a marker'}</Text><TextInput autoFocus multiline onChangeText={(text) => setDraft((value) => ({ ...value, text }))} placeholder={sheet === 'list' ? 'One item per line' : 'Something worth remembering…'} placeholderTextColor={colors.faint} style={[s.sheetInput, s.sheetTextArea]} value={draft.text} /><SheetSave onPress={saveForm} /></View> : null}
      {sheet === 'poll' ? <ScrollView keyboardShouldPersistTaps="handled"><Text style={s.sheetTitle}>Add a poll</Text><TextInput autoFocus onChangeText={(question) => setDraft((value) => ({ ...value, question }))} placeholder="Ask a question" placeholderTextColor={colors.faint} style={s.sheetInput} value={draft.question} />{draft.options.map((option, index) => <TextInput key={index} onChangeText={(text) => setDraft((value) => ({ ...value, options: value.options.map((item, i) => i === index ? text : item) }))} placeholder={`Answer ${index + 1}`} placeholderTextColor={colors.faint} style={s.sheetInput} value={option} />)}{draft.options.length < 4 ? <Pressable onPress={() => setDraft((value) => ({ ...value, options: [...value.options, ''] }))}><Text style={s.inlineAdd}>＋ Add answer</Text></Pressable> : null}<Text style={s.visibilityLabel}>RESULTS</Text><View style={s.visibilityRow}>{[['SUBSCRIBERS', 'Visible'], ['CREATOR', 'Only me']].map(([value, label]) => <Pressable key={value} onPress={() => setDraft((item) => ({ ...item, visibility: value }))} style={[s.visibilityChoice, draft.visibility === value && s.visibilityChoiceOn]}><Text style={s.visibilityText}>{label}</Text></Pressable>)}</View><SheetSave onPress={saveForm} /></ScrollView> : null}
      {voiceError ? <Text style={s.sheetError}>{voiceError}</Text> : null}
    </KeyboardAvoidingView></View></Modal>
  </KeyboardAvoidingView>;
}

function CanvasBlock({ block, onChange, onMove, onRemove }: { block: LocalBlock; onChange: (change: Partial<LocalBlock>) => void; onMove: (direction: -1 | 1) => void; onRemove: () => void }) {
  const metadata = (block.metadata || {}) as { overlayText?: string; overlayColor?: string; question?: string; options?: string[]; transcript?: string; location?: { label?: string }; listItems?: string[] };
  return <View style={s.canvasBlock}><View style={s.canvasControls}><Pressable onPress={() => onMove(-1)}><Ionicons color={colors.faint} name="chevron-up" size={16} /></Pressable><Pressable onPress={() => onMove(1)}><Ionicons color={colors.faint} name="chevron-down" size={16} /></Pressable><Pressable onPress={onRemove}><Ionicons color={colors.faint} name="close" size={16} /></Pressable></View>
    {block.type === 'IMAGE' && block.asset ? <View style={s.canvasImageWrap}><Image source={{ uri: block.asset.uri }} style={s.canvasImage} /><TextInput maxLength={180} onChangeText={(overlayText) => onChange({ metadata: { ...metadata, overlayText, overlayColor: metadata.overlayColor || '#ffffff' } })} placeholder="Write on photo…" placeholderTextColor="rgba(255,255,255,.7)" style={[s.imageOverlay, { color: metadata.overlayColor || '#fff' }]} value={metadata.overlayText || ''} /></View> : null}
    {block.type === 'HIGHLIGHT' ? <TextInput multiline onChangeText={(text) => onChange({ text })} placeholder="Something worth remembering…" placeholderTextColor={colors.faint} style={s.markerBlock} value={block.text || ''} /> : null}
    {block.type === 'KEY_POINT' && metadata.location ? <View style={s.locationChip}><Ionicons color={colors.blue} name="location" size={13} /><Text style={s.locationText}>{metadata.location.label}</Text></View> : null}
    {block.type === 'LIST' ? <View style={s.listBlock}>{String(block.text || '').split('\n').filter(Boolean).map((item, index) => <View key={index} style={s.listRow}><View style={s.listDot} /><Text style={s.listText}>{item}</Text></View>)}</View> : null}
    {block.type === 'LINK' ? <View style={s.linkBlock}><Ionicons color={colors.muted} name="link" size={18} /><View style={{ flex: 1 }}><Text style={s.linkTitle}>{block.label}</Text><Text numberOfLines={1} style={s.linkUrl}>{block.url}</Text></View></View> : null}
    {block.type === 'POLL' ? <View style={s.pollBlock}><Text style={s.pollQuestion}>{metadata.question}</Text>{(metadata.options || []).map((option) => <View key={option} style={s.pollOption}><Text style={s.pollOptionText}>{option}</Text></View>)}</View> : null}
    {block.type === 'VOICE' && block.asset ? <VoiceBlock block={block} onChange={onChange} /> : null}
  </View>;
}

function VoiceBlock({ block, onChange }: { block: LocalBlock; onChange: (change: Partial<LocalBlock>) => void }) { const player = useAudioPlayer(block.asset?.uri || null); const status = useAudioPlayerStatus(player); const metadata = (block.metadata || {}) as { transcript?: string }; return <View style={s.savedVoice}><View style={s.voicePlayer}><Pressable onPress={() => status.playing ? player.pause() : player.play()} style={s.voicePlay}><Ionicons color="#07101A" name={status.playing ? 'pause' : 'play'} size={14} /></Pressable><View style={s.waveform}>{Array.from({ length: 28 }, (_, index) => <View key={index} style={[s.waveBar, { height: 5 + ((index * 7) % 20) }]} />)}</View><Text style={s.voiceDuration}>{Math.floor((status.duration || 0) / 60)}:{String(Math.floor(status.duration || 0) % 60).padStart(2, '0')}</Text></View><TextInput multiline onChangeText={(transcript) => onChange({ metadata: { ...metadata, transcript } })} placeholder="Transcript unavailable — tap to add text" placeholderTextColor={colors.faint} style={s.transcript} value={metadata.transcript || ''} /></View>; }
function SheetSave({ onPress }: { onPress: () => void }) { return <Pressable onPress={onPress} style={s.sheetSave}><Text style={s.sheetSaveText}>Add to chapter</Text></Pressable>; }

function SeenPreview({ cover, title, summary, chapters, onBack }: { cover: Asset | null; title: string; summary: string; chapters: LocalChapter[]; onBack: () => void }) { return <View style={s.previewScreen}><ScrollView contentContainerStyle={{ paddingBottom: 60 }}><Pressable onPress={onBack} style={s.previewBack}><Ionicons color="#fff" name="chevron-back" size={23} /></Pressable>{cover?.type.startsWith('image/') ? <Image source={{ uri: cover.uri }} style={s.previewImage} /> : <View style={[s.previewImage, s.video]}><Ionicons color={colors.blue} name="videocam" size={40} /></View>}<View style={s.previewCopy}><Text style={s.previewTitle}>{title || 'Untitled Seen'}</Text><Text style={s.previewSummary}>{summary}</Text>{chapters.map((chapter, index) => <View key={chapter.id} style={s.previewChapter}><Text style={s.previewNumber}>{String(index + 1).padStart(2, '0')}</Text><Text style={s.previewChapterTitle}>{chapter.title || `Chapter ${index + 1}`}</Text>{chapter.blocks.map((block) => <PreviewBlock block={block} key={block.id} />)}</View>)}</View></ScrollView></View>; }
function PreviewBlock({ block }: { block: LocalBlock }) { const metadata = (block.metadata || {}) as { overlayText?: string; question?: string; options?: string[]; transcript?: string; location?: { label?: string } }; if (block.type === 'IMAGE' && block.asset) return <View style={{ marginBottom: 12 }}><Image source={{ uri: block.asset.uri }} style={s.previewBlockImage} />{metadata.overlayText ? <Text style={s.previewImageOverlay}>{metadata.overlayText}</Text> : null}</View>; if (block.type === 'POLL') return <View style={s.pollBlock}><Text style={s.pollQuestion}>{metadata.question}</Text>{(metadata.options || []).map((option) => <View key={option} style={s.pollOption}><Text style={s.pollOptionText}>{option}</Text></View>)}</View>; if (block.type === 'LINK') return <View style={s.linkBlock}><Ionicons color={colors.muted} name="link" size={18} /><View><Text style={s.linkTitle}>{block.label}</Text><Text style={s.linkUrl}>{block.url}</Text></View></View>; if (block.type === 'VOICE') return <View><View style={s.voicePlayer}><Ionicons color="#07101A" name="play" size={14} /><View style={s.waveform}>{Array.from({ length: 28 }, (_, index) => <View key={index} style={[s.waveBar, { height: 5 + ((index * 7) % 20) }]} />)}</View></View><Text style={s.previewBlock}>{metadata.transcript}</Text></View>; if (metadata.location?.label) return <View style={s.locationChip}><Ionicons color={colors.blue} name="location" size={13} /><Text style={s.locationText}>{metadata.location.label}</Text></View>; return <Text style={[s.previewBlock, block.type === 'HIGHLIGHT' && s.previewHighlight]}>{block.text}</Text>; }
function MediaButton({ icon, label, onPress }: { icon: keyof typeof Ionicons.glyphMap; label: string; onPress: () => void }) { return <Pressable onPress={onPress} style={s.mediaButton}><Ionicons color={colors.blue} name={icon} size={20} /><Text style={s.mediaButtonText}>{label}</Text></Pressable>; }
function Tool({ icon, label, onPress }: { icon: keyof typeof Ionicons.glyphMap; label: string; onPress: () => void }) { return <Pressable onPress={onPress} style={s.tool}><Ionicons color={colors.blue} name={icon} size={20} /><Text style={s.toolText}>{label}</Text></Pressable>; }

